using Microsoft.EntityFrameworkCore;
using Rtres.Domain;

namespace Rtres.Infrastructure.Persistence;

public sealed class RtresDbContext(DbContextOptions<RtresDbContext> options) : DbContext(options)
{
    public DbSet<Client> Clients => Set<Client>(); public DbSet<UserAccount> UserAccounts => Set<UserAccount>(); public DbSet<LoginLink> LoginLinks => Set<LoginLink>();
    public DbSet<Project> Projects => Set<Project>(); public DbSet<ProjectRepository> ProjectRepositories => Set<ProjectRepository>(); public DbSet<PortalNotification> PortalNotifications => Set<PortalNotification>(); public DbSet<Product> Products => Set<Product>(); public DbSet<ClientProduct> ClientProducts => Set<ClientProduct>();
    public DbSet<Ticket> Tickets => Set<Ticket>(); public DbSet<TicketAttachment> TicketAttachments => Set<TicketAttachment>(); public DbSet<TicketComment> TicketComments => Set<TicketComment>(); public DbSet<PaymentTransaction> PaymentTransactions => Set<PaymentTransaction>(); public DbSet<NotificationLog> NotificationLogs => Set<NotificationLog>();
    public DbSet<ExchangeRate> ExchangeRates => Set<ExchangeRate>(); public DbSet<TaxDocument> TaxDocuments => Set<TaxDocument>(); public DbSet<TaxDocumentLine> TaxDocumentLines => Set<TaxDocumentLine>(); public DbSet<PaymentReversal> PaymentReversals => Set<PaymentReversal>(); public DbSet<Purchase> Purchases => Set<Purchase>(); public DbSet<LearningVideo> LearningVideos => Set<LearningVideo>(); public DbSet<ExpenseCategory> ExpenseCategories => Set<ExpenseCategory>(); public DbSet<ProductCategory> ProductCategories => Set<ProductCategory>(); public DbSet<Expense> Expenses => Set<Expense>(); public DbSet<TaxSettings> TaxSettings => Set<TaxSettings>(); public DbSet<TaxDueDate> TaxDueDates => Set<TaxDueDate>(); public DbSet<AnnualTaxSettings> AnnualTaxSettings => Set<AnnualTaxSettings>(); public DbSet<ContactLead> ContactLeads => Set<ContactLead>(); public DbSet<BankAccount> BankAccounts => Set<BankAccount>(); public DbSet<PaymentSettings> PaymentSettings => Set<PaymentSettings>(); public DbSet<TransferReport> TransferReports => Set<TransferReport>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Client>().HasIndex(x => x.Email).IsUnique(); modelBuilder.Entity<UserAccount>().HasIndex(x => x.Email).IsUnique(); modelBuilder.Entity<UserAccount>().Property(x => x.Area).HasMaxLength(100); modelBuilder.Entity<UserAccount>().Property(x => x.JobTitle).HasMaxLength(100); modelBuilder.Entity<UserAccount>().HasOne<UserAccount>().WithMany().HasForeignKey(x => x.ManagerId).OnDelete(DeleteBehavior.NoAction); modelBuilder.Entity<LoginLink>().HasIndex(x => x.TokenHash).IsUnique(); modelBuilder.Entity<LoginLink>().Property(x => x.TokenHash).HasMaxLength(64); modelBuilder.Entity<LoginLink>().Property(x => x.UsedAt).IsConcurrencyToken(); modelBuilder.Entity<LoginLink>().HasOne<UserAccount>().WithMany().HasForeignKey(x => x.UserAccountId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<Project>().HasIndex(x => x.Slug).IsUnique(); modelBuilder.Entity<ClientProduct>().HasIndex(x => x.PayPalSubscriptionId).IsUnique(); modelBuilder.Entity<ClientProduct>().HasIndex(x => x.PayPalOrderId).IsUnique(); modelBuilder.Entity<Ticket>().HasIndex(x => x.Code).IsUnique(); modelBuilder.Entity<Ticket>().HasIndex(x => x.GithubIssueNumber); modelBuilder.Entity<TicketComment>().HasIndex(x => x.GithubCommentId).IsUnique(); modelBuilder.Entity<NotificationLog>().HasIndex(x => x.DedupeKey); modelBuilder.Entity<NotificationLog>().Property(x => x.DedupeKey).HasMaxLength(200);
        modelBuilder.Entity<Product>().Property(x => x.BasePrice).HasPrecision(12, 2); modelBuilder.Entity<Product>().Property(x => x.PayPalPlanPrice).HasPrecision(12, 2); modelBuilder.Entity<ClientProduct>().Property(x => x.Price).HasPrecision(12, 2); modelBuilder.Entity<ClientProduct>().Property(x => x.Discount).HasPrecision(12, 2); modelBuilder.Entity<ClientProduct>().Ignore(x => x.AppliedIgvRate); modelBuilder.Entity<PaymentTransaction>().Property(x => x.Amount).HasPrecision(12, 2); modelBuilder.Entity<PaymentTransaction>().Property(x => x.AmountPen).HasPrecision(12, 2); modelBuilder.Entity<PaymentTransaction>().HasIndex(x => x.InternalCode).IsUnique(); modelBuilder.Entity<PaymentTransaction>().HasIndex(x => new { x.ClientId, x.CreatedAt }); modelBuilder.Entity<TaxDocument>().Property(x => x.RetentionAmount).HasPrecision(12, 2); modelBuilder.Entity<PaymentTransaction>().Property(x => x.Method).HasMaxLength(20); modelBuilder.Entity<PaymentTransaction>().Property(x => x.PayPalOrderIdOrSubscriptionId).HasMaxLength(100); modelBuilder.Entity<PaymentTransaction>().HasIndex(x => x.PayPalOrderIdOrSubscriptionId).IsUnique();
        // Un repo de GitHub pertenece a un solo proyecto: el webhook ubica el ticket por dueño/nombre del repo.
        modelBuilder.Entity<ProjectRepository>().HasIndex(x => new { x.Owner, x.Name }).IsUnique();
        modelBuilder.Entity<ExpenseCategory>().Property(x => x.Name).HasMaxLength(100);
        modelBuilder.Entity<ExpenseCategory>().HasIndex(x => x.Name).IsUnique();
        modelBuilder.Entity<ExpenseCategory>().Property(x => x.Code).HasMaxLength(50);
        modelBuilder.Entity<ExpenseCategory>().HasData(ExpenseCategoryIds.Seed);
        modelBuilder.Entity<Expense>().HasOne(x => x.Category).WithMany().HasForeignKey(x => x.CategoryId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<ProductCategory>().Property(x => x.Name).HasMaxLength(100);
        modelBuilder.Entity<ProductCategory>().HasIndex(x => x.Name).IsUnique();
        modelBuilder.Entity<LearningVideo>().Property(x => x.Title).HasMaxLength(200);
        modelBuilder.Entity<Purchase>().Ignore(x => x.TaxCreditPen);
        foreach (var money in new[] { nameof(Purchase.TaxBase), nameof(Purchase.Igv), nameof(Purchase.NonTaxable), nameof(Purchase.Total), nameof(Purchase.BasePen), nameof(Purchase.IgvPen), nameof(Purchase.TotalPen) }) modelBuilder.Entity<Purchase>().Property(money).HasPrecision(12, 2);
        modelBuilder.Entity<Purchase>().Property(x => x.ExchangeRate).HasPrecision(12, 6);
        modelBuilder.Entity<Purchase>().HasIndex(x => new { x.SupplierTaxId, x.DocumentType, x.Series, x.Number }).IsUnique();
        modelBuilder.Entity<Purchase>().HasIndex(x => x.Period);
        modelBuilder.Entity<Purchase>().Property(x => x.Series).HasMaxLength(20);
        modelBuilder.Entity<Purchase>().Property(x => x.Number).HasMaxLength(20);
        modelBuilder.Entity<Purchase>().Property(x => x.SupplierTaxId).HasMaxLength(20);
        modelBuilder.Entity<Purchase>().Property(x => x.SupplierName).HasMaxLength(200);
        modelBuilder.Entity<Purchase>().Property(x => x.Currency).HasMaxLength(3);
        modelBuilder.Entity<Purchase>().Property(x => x.Notes).HasMaxLength(500);
        modelBuilder.Entity<LearningVideo>().Property(x => x.YoutubeId).HasMaxLength(11);
        modelBuilder.Entity<LearningVideo>().Property(x => x.Category).HasMaxLength(100);
        modelBuilder.Entity<LearningVideo>().Property(x => x.Language).HasMaxLength(2);
        modelBuilder.Entity<LearningVideo>().Property(x => x.Description).HasMaxLength(500);
        modelBuilder.Entity<TicketAttachment>().Ignore(x => x.IsImage);
        modelBuilder.Entity<TicketAttachment>().Property(x => x.ContentType).HasMaxLength(100);
        modelBuilder.Entity<TicketAttachment>().Property(x => x.FileName).HasMaxLength(255);
        modelBuilder.Entity<ProjectRepository>().Property(x => x.Owner).HasMaxLength(100);
        modelBuilder.Entity<ProjectRepository>().Property(x => x.Name).HasMaxLength(100);
        modelBuilder.Entity<ProjectRepository>().Property(x => x.Label).HasMaxLength(100);
        modelBuilder.Entity<PortalNotification>().HasIndex(x => new { x.ClientId, x.CreatedAt }); modelBuilder.Entity<PortalNotification>().HasIndex(x => x.DedupeKey); modelBuilder.Entity<PortalNotification>().Property(x => x.Type).HasMaxLength(40); modelBuilder.Entity<PortalNotification>().Property(x => x.DedupeKey).HasMaxLength(200);
        modelBuilder.Entity<Product>().Property(x => x.Category).HasMaxLength(100); modelBuilder.Entity<Product>().Property(x => x.Tags).HasMaxLength(500);
        modelBuilder.Entity<ExchangeRate>().HasIndex(x => new { x.Date, x.CurrencyCode }).IsUnique(); modelBuilder.Entity<ExchangeRate>().Property(x => x.RateToPen).HasPrecision(12, 6);
        modelBuilder.Entity<PaymentReversal>().Property(x => x.Amount).HasPrecision(12, 2); modelBuilder.Entity<PaymentReversal>().Property(x => x.AmountPen).HasPrecision(12, 2); modelBuilder.Entity<PaymentReversal>().Property(x => x.PaymentKey).HasMaxLength(100); modelBuilder.Entity<PaymentReversal>().Property(x => x.Method).HasMaxLength(20); modelBuilder.Entity<PaymentReversal>().Property(x => x.Reason).HasMaxLength(500); modelBuilder.Entity<PaymentReversal>().HasIndex(x => x.PaymentKey);
        modelBuilder.Entity<TaxDocument>().HasIndex(x => new { x.Type, x.Series, x.Number }).IsUnique(); modelBuilder.Entity<TaxDocumentLine>().Property(x => x.Amount).HasPrecision(12, 2); modelBuilder.Entity<TaxDocumentLine>().Property(x => x.Description).HasMaxLength(300); modelBuilder.Entity<TaxDocumentLine>().HasOne<TaxDocument>().WithMany().HasForeignKey(x => x.TaxDocumentId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<TaxDocumentLine>().HasOne<ClientProduct>().WithMany().HasForeignKey(x => x.ClientProductId).OnDelete(DeleteBehavior.NoAction); modelBuilder.Entity<TaxDocument>().HasIndex(x => x.PaymentTransactionId).IsUnique().HasFilter("[PaymentTransactionId] IS NOT NULL"); modelBuilder.Entity<TaxSettings>().Property(x => x.FacturaSeries).HasMaxLength(4); modelBuilder.Entity<TaxSettings>().Property(x => x.ReciboSeries).HasMaxLength(4); modelBuilder.Entity<TaxDocument>().Property(x => x.BaseAmount).HasPrecision(12, 2); modelBuilder.Entity<TaxDocument>().Property(x => x.IgvAmount).HasPrecision(12, 2); modelBuilder.Entity<TaxDocument>().Property(x => x.TotalAmount).HasPrecision(12, 2);
        modelBuilder.Entity<Expense>().Property(x => x.Amount).HasPrecision(12, 2); modelBuilder.Entity<Expense>().Property(x => x.AmountPen).HasPrecision(12, 2);
        modelBuilder.Entity<TaxSettings>().Property(x => x.Ruc).HasMaxLength(11); modelBuilder.Entity<TaxDueDate>().HasIndex(x => x.Period).IsUnique(); modelBuilder.Entity<TaxDueDate>().HasData(TaxDueDateSeed.Rows2026);
        modelBuilder.Entity<ClientProduct>().Ignore(x => x.TransferReport);
        modelBuilder.Entity<ContactLead>().Property(x => x.Name).HasMaxLength(150); modelBuilder.Entity<ContactLead>().Property(x => x.Email).HasMaxLength(200); modelBuilder.Entity<ContactLead>().Property(x => x.Phone).HasMaxLength(40); modelBuilder.Entity<ContactLead>().Property(x => x.Company).HasMaxLength(150); modelBuilder.Entity<ContactLead>().Property(x => x.Service).HasMaxLength(60); modelBuilder.Entity<ContactLead>().Property(x => x.Message).HasMaxLength(4000); modelBuilder.Entity<ContactLead>().Property(x => x.Locale).HasMaxLength(2); modelBuilder.Entity<ContactLead>().Property(x => x.SourcePage).HasMaxLength(200); modelBuilder.Entity<ContactLead>().Property(x => x.Notes).HasMaxLength(1000); modelBuilder.Entity<ContactLead>().Property(x => x.Status).HasConversion<string>().HasMaxLength(20); modelBuilder.Entity<ContactLead>().HasIndex(x => x.CreatedAt);
        modelBuilder.Entity<AnnualTaxSettings>().HasIndex(x => x.Year).IsUnique(); modelBuilder.Entity<AnnualTaxSettings>().Property(x => x.Uit).HasPrecision(12, 2); modelBuilder.Entity<AnnualTaxSettings>().Property(x => x.ThresholdUits).HasPrecision(6, 2); modelBuilder.Entity<AnnualTaxSettings>().Property(x => x.LowRate).HasPrecision(5, 4); modelBuilder.Entity<AnnualTaxSettings>().Property(x => x.HighRate).HasPrecision(5, 4);
        modelBuilder.Entity<AnnualTaxSettings>().HasData(new AnnualTaxSettings { Id = new Guid("a7000000-0000-0000-0000-000000002026"), Year = 2026, Uit = 5500m });
        modelBuilder.Entity<Expense>().Property(x => x.ForeignSupplierName).HasMaxLength(200); modelBuilder.Entity<Expense>().Property(x => x.ForeignSupplierCountry).HasMaxLength(100); modelBuilder.Entity<Expense>().Property(x => x.Form1662Number).HasMaxLength(40);
        modelBuilder.Entity<TaxDueDate>().Property(x => x.IgvPaid).HasPrecision(12, 2); modelBuilder.Entity<TaxDueDate>().Property(x => x.RentaPaid).HasPrecision(12, 2);
        modelBuilder.Entity<BankAccount>().Property(x => x.BankName).HasMaxLength(100); modelBuilder.Entity<BankAccount>().Property(x => x.Holder).HasMaxLength(200); modelBuilder.Entity<BankAccount>().Property(x => x.Currency).HasMaxLength(3); modelBuilder.Entity<BankAccount>().Property(x => x.AccountNumber).HasMaxLength(40); modelBuilder.Entity<BankAccount>().Property(x => x.Cci).HasMaxLength(40); modelBuilder.Entity<BankAccount>().Property(x => x.Type).HasConversion<string>().HasMaxLength(20);
        modelBuilder.Entity<TransferReport>().Property(x => x.Amount).HasPrecision(12, 2); modelBuilder.Entity<TransferReport>().Property(x => x.Currency).HasMaxLength(3); modelBuilder.Entity<TransferReport>().Property(x => x.OperationNumber).HasMaxLength(60); modelBuilder.Entity<TransferReport>().Property(x => x.ReceiptFileName).HasMaxLength(255); modelBuilder.Entity<TransferReport>().Property(x => x.ReceiptContentType).HasMaxLength(100); modelBuilder.Entity<TransferReport>().Property(x => x.RejectionReason).HasMaxLength(500); modelBuilder.Entity<TransferReport>().Property(x => x.Status).HasConversion<string>().HasMaxLength(20); modelBuilder.Entity<TransferReport>().HasIndex(x => new { x.Status, x.CreatedAt }); modelBuilder.Entity<TransferReport>().HasIndex(x => x.ClientProductId);
        modelBuilder.Entity<TaxSettings>().Property(x => x.IgvRate).HasPrecision(5, 4); modelBuilder.Entity<TaxSettings>().Property(x => x.RentaRate).HasPrecision(5, 4);
    }
}
